import React from 'react';
import { BrowserRouter as Router,Route,Routes } from 'react-router-dom';
import Header from "../src/Componets/Header/Header";
import Analysis from './Componets/Analysis/Anaysis';
import Constult from './Componets/Constult/Constult';
import Uploads from "./Componets/Uploads/Uploads";

function App() {
  return (
   <Router>
   <Routes>
    <Route path='/' element={<Header/>}/>
    <Route path='/Upload' element={<Uploads/>}/>
    <Route path='/Constult' element={<Constult/>}/>

   </Routes>
   </Router>
  );
}

export default App;
